Modbus_threshold_settingViewBase::~Modbus_threshold_settingViewBase()
{

}

void Modbus_threshold_settingViewBase::setupScreen()
{
    keyboard_modbus1.initialize();
}

void Modbus_threshold_settingViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &back)
    {
        //back
        //When back clicked change screen to Setting
        //Go to Setting with no screen transition
        application().gotoSettingScreenNoTransition();
    }
    if (&src == &save)
    {
        //modbus_save
        //When save clicked call virtual function
        //Call modbus_threshold_save_cb
        modbus_threshold_save_cb();
    }
}

